# -*- coding: utf-8 -*-
LUK = dict(id="luk", n="路加福音", ab="路", en="Luke", ic="🩺", col="#4cd3c2", ch=24, fn="luke.html",
 port="万人的救主（完全的人）", sym="🐂 牛（耶柔米传统：以圣殿献祭的祭司撒迦利亚开头）", aud="外邦读者（提阿非罗）", stamp="“今天……救恩”",
 au="路加，“亲爱的医生”（{{西4:14}}），保罗的同工（{{提后4:11}}）；同时写了使徒行传（{{徒1:1}}），两卷书合占新约约四分之一篇幅",
 date="约主后 60–62 年（使徒行传结束于保罗在罗马被软禁，路加福音写在其前）", place="该撒利亚或罗马（保罗受审期间）",
 to="“提阿非罗大人”（{{路1:3}}）及广大外邦慕道者与信徒", fr="caesarea", dest="rome", acts="路1:1-4；徒1:1-3",
 kw="救恩", core="神按着应许，在历史中差来救主耶稣，叫被藐视的、贫穷的、罪人与外邦人都得着救恩；“人子来，为要寻找、拯救失丧的人”。",
 kv="路19:10", mn="四首诗歌开幕 → 拿撒勒宣言（4:18）→ 定意上耶路撒冷（9:51）→ 旅程中的比喻（失羊·失钱·失子）→ 十字架上的赦免 → 以马忤斯的圣经课",
 bg="路加是外邦人（{{西4:11-14}}的区分暗示），受过良好希腊教育，序言（1:1-4）是标准的希腊史学文体。他在保罗于该撒利亚被囚的两年间（{{徒24:27}}），很可能在犹太地访问了马利亚等“从起初亲眼看见”的人，**“从起头都详细考察了”**（{{路1:3}}），写成按次序的叙述，使提阿非罗“知道所学之道都是确实的”。路加把耶稣放在罗马帝国的世界史中（该撒亚古士督、居里扭、提庇留十五年），说明福音不是“在背地里做的”（{{徒26:26}}）。",
 cul="**希腊—罗马世界**：赞助人献书（提阿非罗）、宴席文化（路加记载许多饭桌场景，饭桌上谁坐首位是身份象征，14:7-11）、恩庇制度（施恩者期待回报，耶稣反其道：请贫穷残废的，14:12-14）。**撒玛利亚人**被犹太人视为混血异端，耶稣却以他为爱邻舍的榜样（10:30-37）。**妇女**在路加中特别显著：以利沙伯、马利亚、亚拿、马大与马利亚、跟随供给的妇女（8:1-3）。",
 why=["向外邦有识之士按史学方式证实福音（1:1-4）","说明救恩临到贫穷、罪人、妇女、外邦人——福音是普世的","在罗马法庭前表明基督教在政治上无害（彼拉多三次宣告无罪）","为使徒行传铺路：从耶路撒冷到地极"],
 ol=[("1–2","降生故事与四首诗歌：神记念祂的圣约",2),("3:1–4:13","预备：约翰、家谱（追溯到亚当）、试探",1.5),("4:14–9:50","加利利事工：拿撒勒宣言、医治、赦罪、门徒",6),("9:51–19:27","上耶路撒冷的旅程：比喻与门徒教导（路加独有材料集中于此）",9),("19:28–21:38","耶路撒冷：进城、圣殿教训、末世讲论",2.5),("22–23","受难：晚餐、客西马尼、审判、十字架上的赦免",2),("24","复活、以马忤斯、升天",1)],
 bt="路加的家谱一路追到「亚当，亚当是神的儿子」（{{路3:38}}）：耶稣是**末后的亚当**，要为全人类成就第一个亚当失败之事；紧接着祂在旷野胜过试探。拿撒勒会堂中耶稣读以赛亚书 61 章并宣告“今天这经应验在你们耳中了”（{{路4:21}}），宣布**禧年**的实现——真正的释放是罪得赦免。复活的主对以马忤斯的门徒“从摩西和众先知起，凡经上所指着自己的话都给他们讲解明白了”（{{路24:27}}），又说“摩西的律法、先知的书，和诗篇上所记的，凡指着我的话都必须应验”（{{路24:44}}）——这就是**整本圣经以基督为中心**的读经法，也是本站“圣经神学”的根据。",
 ct="四首诗歌把耶稣的降生定位在==圣约的信实==中：马利亚颂「正如从前对我们列祖亚伯拉罕和他后裔所说的话」（{{路1:55}}）；撒迦利亚颂说神「记念他的圣约，就是他对我们祖宗亚伯拉罕所起的誓」（{{路1:72-73}}），又称祂“在他仆人大卫家中，为我们兴起了拯救的角”（{{路1:69}}）。耶稣第八天受割礼（{{路2:21}}），在旧约之下为我们成全律法。最后晚餐：“这杯是用我血所立的新约，是为你们流出来的”（{{路22:20}}），直接引用耶利米书 31 章的“新约”。",
 key=["**救恩“今天”临到**：{{路2:11}}；{{路4:21}}；{{路19:9}}；{{路23:43}}","**寻找失丧的人**：15 章三个比喻、撒该（19:1-10）","**圣灵与祷告**：耶稣受洗时在祷告（3:21），常退到旷野祷告（5:16）；天父必将圣灵给求他的人（11:13）","**财富与贫穷**：无知的财主（12:16-21）、财主与拉撒路（16:19-31）","**普世的福音**：西面称祂是“照亮外邦人的光”（{{路2:32}}）；结尾“传到万邦”（{{路24:47}}）"],
 hard=[("!!居里扭的人口普查（2:2）是否与史实冲突？!!","罗马史料记载居里扭于主后 6 年任叙利亚巡抚并进行普查，而耶稣生于希律死（主前 4 年）之前。可能的解决：①“头一次”可译为「在居里扭作叙利亚巡抚**以前**」的普查；②居里扭早年曾在该地区担任军政要职，参与先前的登记；③罗马在附庸国的登记常历时多年。路加在使徒行传 5:37 清楚知道主后 6 年的“报名上册”，说明他有意区分。证据不足以断定路加出错。"),
  ("!!马太与路加的家谱为什么不同？!!","马太从亚伯拉罕往下，经所罗门（王位的合法继承线）；路加从耶稣往上追到亚当，经拿单。常见解释：①路加记的是**马利亚的家谱**（希利是马利亚的父亲，约瑟是“女婿”意义上的儿子）；②一条是法定继承线、一条是血缘线，中间有寡嫂制（申25）造成的交叉。两者都证明耶稣是大卫的后裔。"),
  ("!!不义的管家（16:1-13）：耶稣在称赞不诚实吗？!!","主人“夸奖”的是管家的**精明**，不是他的不义：他用眼前的机会为将来打算。耶稣的教训：“要藉着那不义的钱财结交朋友，到了钱财无用的时候，他们可以接你们到永存的帐幕里去”（{{路16:9}}）——用暂时的财富为永恒投资，接着就说“你们不能又事奉神，又事奉玛门”（16:13）。"),
  ("!!“今日你要同我在乐园里了”（23:43）与“灵魂睡觉”、炼狱!!","这句话表明信徒死后**灵魂立即与基督同在**，既没有“灵魂睡觉”，也没有炼狱。WCF 32.1 说义人的灵魂「立时归回赐灵魂的神那里」，在天上等候身体的完全救赎。强盗毫无善功，却凭信靠得救——这正是唯独恩典的最佳例证。")],
 conf=[("bc",17),("hc",35),("bc",18,"这位独生子取了真正的人性及其诸般的软弱，只是没有罪，因为他是藉着圣灵的大能，而不是藉着人的作为，在蒙恩的童女马利亚腹中成孕的。"),("hc",36),("hc",46),("hc",1)],
 ws=[("wcf",32,1)],
 sermon=("/sermons/text/100","其中一个人努力说服自己已经得救了，但实际上他并没有得救；而另一个人根本不敢想自己得救的事，但他却真的得救了。"),
 sermon2=("/sermons/text/102","基于这一事实，主耶稣要我们带着永生的视角来使用今生的财富。"),
 app=["读 15 章时把自己放进大儿子的位置：我是否也在父家里却不懂父心？","用 18:9-14 检查祷告：我是否在神面前列举自己的功劳？","按 14:12-14 开放你的饭桌给不能回报你的人。","像以马忤斯的门徒那样，读旧约时问：这段经文如何指向基督？"],
 ang={"历史":"按希腊史学方法写成的“两卷本”第一卷","文学":"旅行叙事（9:51–19:27）、对比结构、诗歌、宴席场景","神学":"救恩论、圣灵论、祷告、普世宣教","牧养":"失丧者的盼望、财富观、谦卑的义"},
 uniq=["施洗约翰的出生、天使报信、四首诗歌（1–2 章）","耶稣十二岁在圣殿（2:41-52）","好撒玛利亚人、无知的财主、失羊失钱浪子、不义的管家、财主与拉撒路、法利赛人与税吏（10–18 章）","撒该（19:1-10）、十个长大麻风的（17:11-19）","十字架上三句话：“父啊，赦免他们”“今日你要同我在乐园里”“父啊，我将我的灵魂交在你手里”","以马忤斯路上（24:13-35）与升天（24:50-53）"])

JHN = dict(id="jhn", n="约翰福音", ab="约", en="John", ic="🦅", col="#8f8bff", ch=21, fn="john.html",
 port="道成肉身的神子", sym="🦅 鹰（耶柔米传统：从“太初有道”高飞到永恒）", aud="小亚细亚教会与慕道者", stamp="“我是……”",
 au="使徒约翰，西庇太的儿子，自称“耶稣所爱的那门徒”（{{约21:20-24}}）；爱任纽（坡旅甲的学生）明确说约翰在以弗所写成此书",
 date="约主后 85–95 年", place="以弗所",
 to="小亚细亚的教会，以及需要相信的读者（20:31）", fr="ephesus", dest="ephesus", acts="约1:1-18；约20:30-31",
 kw="信 · 生命", core="太初与神同在、本身就是神的道成了肉身；祂藉七个神迹和七个“我是”显明自己是基督、神的儿子，并在十字架上被举起得荣耀，叫信的人因祂的名得生命。",
 kv="约20:31", mn="序言（道·光·生命）→ 七神迹（2–11 章“神迹之书”）→ 七“我是” → 楼上讲论（13–17 章）→ “成了”（19:30）→ 多马认信“我的主，我的神”",
 bg="写作时，对观福音已在教会中流传多年。约翰以年老使徒的身份写下**补充性、深思性的见证**：①大量记载耶稣在犹太地与耶路撒冷的事工（至少三次逾越节，2:13；6:4；11:55），②记录长篇讲论与私下谈话，③面对两种错误：否认耶稣真有肉身的早期幻影派思想（“道成了肉身”1:14），以及否认耶稣是神的犹太会堂立场（“他是神”1:1）。目的清楚写在 20:31。",
 cul="**以弗所的希腊化世界**：“道”（Logos）在希腊哲学中指宇宙的理性原则，在犹太传统中让人想起神创造的话（创1）与智慧（箴8）。约翰借用这个词，却宣告这道是**一个位格**，而且“成了肉身”——这对哲学家是丑闻，对犹太人是亵渎。**犹太节期**是约翰的叙事骨架：安息日、逾越节、住棚节（灯与水的仪式，7:37；8:12）、修殿节（10:22）——耶稣在每个节期上宣告自己是节期所指的实体。",
 why=["叫人相信耶稣是基督、是神的儿子，并因信得生命（20:31）","补充对观福音未记的犹太事工与讲论","驳斥否认道成肉身与否认基督神性的错误","坚固遭会堂驱逐的信徒（9:22；16:2）"],
 ol=[("1:1-18","序言：道、光、生命、道成肉身",1),("1:19–4:54","开始显出荣耀：迦拿、洁净圣殿、尼哥底母、撒玛利亚妇人",3.5),("5–10","节期中的冲突：安息日、生命的粮、住棚节、生来瞎眼的、好牧人",6),("11–12","拉撒路复活与时候到了",2),("13–17","楼上讲论：洗脚、新命令、保惠师、葡萄树、大祭司的祷告",5),("18–19","被举起：被捕、审判、十字架、埋葬",2),("20–21","复活显现与恢复彼得",2)],
 bt="“太初有道”（{{约1:1}}）直接接续创世记 1:1：创造世界的道如今来**新创造**。“道成了肉身，住在我们中间”（{{约1:14}}）中“住”原意是“支搭帐幕”——会幕与圣殿中神的荣耀如今在耶稣身上显明；祂称自己的身体是殿（{{约2:21}}）。耶稣是**真吗哪**（6 章，对照出 16）、**被举起的铜蛇**（3:14，对照民 21）、**逾越节的羔羊**（1:29；19:36 引出12:46“骨头一根也不可折断”）、**好牧人**（10 章，对照结 34 章神亲自牧养）。复活的主向门徒“吹一口气”（{{约20:22}}），正如神向亚当吹气——新人类开始了。",
 ct="“律法本是藉着摩西传的；恩典和真理都是由耶稣基督来的”（{{约1:17}}）：这不是说旧约没有恩典，而是旧约的影儿与应许在基督里有了实体与充满。耶稣在楼上的祷告（17 章）显明==救赎之约==（pactum salutis）：父将一群人“赐给”子（17:2,6,9,24），子来完成父托付的工（17:4），并为“你所赐给我的人”祈求，“不为世人祈求”（{{约17:9}}）。好牧人“为羊舍命”（{{约10:11}}），“我的羊听我的声音……我又赐给他们永生，他们永不灭亡”（{{约10:27-28}}）——圣约中保为选民舍命，并保守他们到底。",
 key=["**七个神迹**：变水为酒、医大臣之子、医毕士大病人、五饼二鱼、行在海面、医生来瞎眼的、叫拉撒路复活","**七个“我是”**：生命的粮、世界的光、羊的门、好牧人、复活与生命、道路真理生命、真葡萄树——回应出 3:14 的“我是自有永有的”（另见 8:58）","**相信与生命**：“信”的动词出现近百次","**时候**：“我的时候还没有到”（2:4）到“时候到了”（12:23；17:1）","**保惠师圣灵**：14–16 章，圣灵引导门徒进入一切真理"],
 hard=[("!!行淫时被拿的妇人（7:53–8:11）是否属于原文？!!","这段不见于最早的抄本，在某些抄本中位置也不同（甚至放在路加福音中），和合本以括号标示。多数改革宗学者认为它很可能是**真实的历史事件**，但不属于约翰原稿，因此不应单凭此段建立教义。它的信息（恩典与“从此不要再犯罪”并存）与全本圣经一致。"),
  ("!!约翰与对观福音在受难日期上不同？!!","对观福音记载最后晚餐是逾越节筵席（{{可14:12}}），约翰却说审判时犹太人还「要吃逾越节的筵席」（{{约18:28}}），并说那日是「逾越节的预备日」（19:14）。可能的解释：①“逾越节”在约翰中可指整个七天的节期（包括除酵节的献祭餐）；②“预备日”指逾越节周期间安息日的预备日（即星期五）。两者都指向同一事实：耶稣在星期五被钉，正是真逾越节羔羊。"),
  ("!!“你们若不吃人子的肉，不喝人子的血”（6:53）：是否支持化质说？!!","耶稣说这话时还没有设立圣餐；上下文把“吃”等同于“信”（6:35,40,47）。耶稣自己说：“叫人活着的乃是灵，肉体是无益的。我对你们所说的话就是灵，就是生命”（{{约6:63}}）。BC 35 指出：信徒凭信心吃喝基督，而饼与酒的本质并不改变。"),
  ("!!“神爱世人”（3:16）与有限的救赎（特定救赎）冲突吗？!!","“世人”在约翰中强调的是世界的**败坏与敌对**（1:10；15:18）和**范围**（不只犹太人），神的爱之大正在于爱这样的世界。经文本身说明受益者：“叫一切信他的”。多特信经第二项教义：基督的死“极其充足”，足以赎尽全世界的罪（2.3），福音要无区别地向万民宣告（2.5）；而神的旨意是叫基督的死有效地救赎所有被拣选的人（2.8）。")],
 conf=[("bc",10,"他不是从取了我们人性那一刻起才成为神的儿子，而是在永恒中就是神的儿子"),("hc",33),("dort",2,5),("dort",2,8),("bc",35,"当信徒吃他的时候，即凭信心领受耶稣基督的时候，他们的属灵生命就得到基督的喂养。"),("dort",5,8)],
 sermon=("/sermons/text/99","对于这个充满黑暗和死亡的世界，约翰写下了光明和生命；对这个听不到耶和华神声音的世界，约翰讲述了神的道。"),
 app=["每天用一个“我是”敬拜主：今天我需要祂作我的粮、光、牧人、道路……","在疑惑中像多马一样把问题带到主面前，并以“我的主，我的神”作结（20:28）。","以洗脚的方式彼此相爱（13:14,34-35）。","住在葡萄树上：读经、祷告、顺服，结果子是自然的结果（15:4-8）。"],
 ang={"历史":"年老使徒在以弗所的补充见证","文学":"序言—神迹之书—荣耀之书—结语；双关语与误解（重生、活水、粮）","神学":"基督的神性与人性、三一、救赎之约、圣灵、永生","牧养":"确据：信的人有永生（5:24；10:28）"},
 uniq=["序言“太初有道”（1:1-18）","迦拿婚宴、尼哥底母、撒玛利亚妇人（2–4 章）","毕士大池、生来瞎眼的、拉撒路复活（5；9；11 章）","洗脚与楼上讲论、大祭司的祷告（13–17 章）","“成了”（19:30）、多马认信（20:28）","提比哩亚海边恢复彼得：“你爱我吗？”（21 章）"])
